            expect(app1Xml.content).toContain('<applicability>applicability_1</applicability>')
            expect(app1Xml.content).toContain('<order>0</order>')
            expect(app1Xml.content).toContain('<active>true</active>')

            const app2Xml = applicabilityXmls.find((x) => x.content.includes(app2Id))
            expect(app2Xml.content).toContain('<applicability>applicability_2</applicability>')
